function ltExerciseInstructions(e,m){
  const base=LT_INS[e.id];
  if(base){
    const parts=base.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean);
    if(parts.length>=3)return parts.slice(0,5);
    const first=parts[0]||base;
    const clauses=first.split(/,\s+/).filter(Boolean);
    const step1=clauses.length>1?clauses[0]+".":first;
    const step2=clauses.length>1?clauses.slice(1).join(", ").replace(/[.]?$/,"."):"Atlikite pagrindinį judesį lėtai ir kontroliuojamai, išlaikydami taisyklingą kūno padėtį.";
    const step3=parts[1]||"Kontroliuojamai grįžkite į pradinę padėtį ir pakartokite judesį.";
    return [step1,step2,step3];
  }
  return (m?.instructions||[]).slice(0,5).map((x,i)=>i===0?"Pradinė padėtis: atlikite pratimą pagal parodytą padėtį.":i===1?"Judesys: atlikite judesį lėtai ir kontroliuojamai.":"Kontroliuojamai grįžkite į pradinę padėtį.");
}
function openExerciseInfo(eid){const e=S.exercises.find(x=>x.id===eid);if(!e)return;const m=exerciseMediaInfo(e);const imgs=m?.images||[];const gallery=imgs.length>1?`<div class="exerciseGallery">${imgs.slice(0,2).map(src=>`<img src="https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/${src}" alt="${esc(e.name?.[S.lang]||e.name?.en||"")}" onerror="this.style.display='none'">`).join("")}</div>`:exerciseImageTag(e,"exerciseHero",true);const instructions=S.lang==='lt'?ltExerciseInstructions(e,m):(m?.instructions||[]).slice(0,5);const equipment=m?.equipment?(S.lang==='lt'?(equipLt[m.equipment]||m.equipment):m.equipment):"";modal(`<div class="exerciseInfo">${gallery}<h2>${esc(e.name[S.lang])}</h2><div class="pill" style="display:inline-block;margin-bottom:10px">${esc(e.muscle[S.lang])}</div>${equipment?`<div class="muted" style="margin-bottom:10px">${esc(S.lang==='lt'?'Įranga: ':'Equipment: ')}${esc(equipment)}</div>`:""}${instructions.length?`<h3>${S.lang==='lt'?'Atlikimas':'How to perform'}</h3><ol>${instructions.map(x=>`<li>${esc(x)}</li>`).join("")}</ol>`:`<p class="muted">${S.lang==='lt'?'Informacija apie pratimą dar neparuošta.':'Exercise information'}</p>`}</div>`)}
async function loadExerciseMedia(){try{const r=await fetch('https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/dist/exercises.json',{cache:'force-cache'});if(!r.ok)return;EXDB=await r.json();EXDB_READY=true;S.exercises.forEach(e=>exerciseMediaInfo(e));document.querySelectorAll('.view.active').forEach(v=>render(v.id))}catch(e){EXDB_READY=false}}
loadExerciseMedia();
